#include <cstdio>
#include <vector>
#include <string>
#include <stack>
#include <iostream>

int main() {
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    std::vector<std::string> grid(rows);
    for (int i = 0; i < rows; ++i) std::cin >> grid[i];

    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};
    int cnt = 0;

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j] != '1') continue;
            ++cnt;
            // 显式栈 DFS，避免大网格递归爆栈
            std::stack<std::pair<int,int>> st;
            grid[i][j] = '0';
            st.push({i, j});
            while (!st.empty()) {
                auto [x, y] = st.top(); st.pop();
                for (int d = 0; d < 4; ++d) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx < 0 || nx >= rows || ny < 0 || ny >= cols) continue;
                    if (grid[nx][ny] != '1') continue;
                    grid[nx][ny] = '0';
                    st.push({nx, ny});
                }
            }
        }
    }
    printf("%d\n", cnt);
    return 0;
}
